package mdcu

// POST-HOC comass diagnostic for round 3 (R3-Q1).
//
// STATUS: this is NOT part of the frozen R3-Q1 analysis and changes no verdict.
// It was requested before the run (arch seq 57: "psi_comass_proxy = ||g||_op^3 and
// an optional sampled max|psi|"), was not built in time, and the run went ahead
// without it (arch seq 59, disclosed on seq 62). It is computed after the fact from
// the seed's own sampler streams, and is labelled post-hoc everywhere it is shown.
//
// Nothing here modifies the frozen samplers (r3forms.go). The forms are
// regenerated by calling SampleS1 / SampleS2 with the grid seed; the S2 spectrum
// is recomputed by replaying the same RNG consumption order, and
// TestS2SpectrumMatchesSampleS2 pins that replay to SampleS2's own outputs.
//
// Comass of a 3-form f on R^7 is the maximum of |f(u,v,w)| over orthonormal
// triples (equivalently over unit simple 3-vectors). comass(phi) = 1.
// ComassEstimate is a multistart ascent, so it is a LOWER bound on the true comass.

import (
	"math"
	"math/rand/v2"
)

// Stream tags for the diagnostic's own RNG. Distinct from every round-2/3 constant.
const (
	postHocSeedA uint64 = 0x2545f491
	postHocSeedB uint64 = 0x4cf5ad43
	postHocStart        = 40
	postHocIters        = 300
)

// comassRandTriple draws a random orthonormal triple in the imaginary 7-space
// (components 1..7; component 0 is zero), by Gram-Schmidt on Gaussian vectors.
func comassRandTriple(rng *rand.Rand) (u, v, w [8]float64) {
	for {
		for k := 1; k < 8; k++ {
			u[k], v[k], w[k] = rng.NormFloat64(), rng.NormFloat64(), rng.NormFloat64()
		}
		if orthonormalize3(&u, &v, &w) {
			return
		}
	}
}

// orthonormalize3 is Gram-Schmidt in the order u, v, w. It reports false on a
// (numerically) degenerate input.
func orthonormalize3(u, v, w *[8]float64) bool {
	vs := [3]*[8]float64{u, v, w}
	for i := 0; i < 3; i++ {
		for j := 0; j < i; j++ {
			d := 0.0
			for k := 1; k < 8; k++ {
				d += vs[i][k] * vs[j][k]
			}
			for k := 1; k < 8; k++ {
				vs[i][k] -= d * vs[j][k]
			}
		}
		n := 0.0
		for k := 1; k < 8; k++ {
			n += vs[i][k] * vs[i][k]
		}
		if n < 1e-24 {
			return false
		}
		n = math.Sqrt(n)
		for k := 1; k < 8; k++ {
			vs[i][k] /= n
		}
	}
	return true
}

// ComassEstimate returns a lower bound on comass(f): the best value found by
// `starts` monotone ascents (Riemannian gradient on the Stiefel manifold V3(R^7),
// QR retraction, backtracking line search), each from a random orthonormal triple
// drawn in order from rng. Deterministic given rng.
func ComassEstimate(f *Form3, rng *rand.Rand, starts, iters int) float64 {
	best := 0.0
	for s := 0; s < starts; s++ {
		u, v, w := comassRandTriple(rng)
		val := f.Eval(u[:], v[:], w[:])
		if val < 0 { // f is alternating: swapping two arguments flips the sign
			for k := 1; k < 8; k++ {
				w[k] = -w[k]
			}
			val = -val
		}
		eta := 1.0
		for it := 0; it < iters; it++ {
			X := [3]*[8]float64{&u, &v, &w}
			var D [3][8]float64
			D[0] = f.GradArg(u[:], v[:], w[:], 0)
			D[1] = f.GradArg(u[:], v[:], w[:], 1)
			D[2] = f.GradArg(u[:], v[:], w[:], 2)
			// Riemannian gradient: xi = D - X sym(X^T D)
			var M [3][3]float64
			for a := 0; a < 3; a++ {
				for b := 0; b < 3; b++ {
					for k := 1; k < 8; k++ {
						M[a][b] += X[a][k] * D[b][k]
					}
				}
			}
			var xi [3][8]float64
			norm2 := 0.0
			for b := 0; b < 3; b++ {
				for k := 1; k < 8; k++ {
					x := D[b][k]
					for a := 0; a < 3; a++ {
						x -= X[a][k] * 0.5 * (M[a][b] + M[b][a])
					}
					xi[b][k] = x
					norm2 += x * x
				}
			}
			if norm2 < 1e-28 {
				break
			}
			improved := false
			for eta > 1e-14 {
				nu, nv, nw := u, v, w
				ns := [3]*[8]float64{&nu, &nv, &nw}
				for b := 0; b < 3; b++ {
					for k := 1; k < 8; k++ {
						ns[b][k] += eta * xi[b][k]
					}
				}
				if orthonormalize3(&nu, &nv, &nw) {
					if nval := f.Eval(nu[:], nv[:], nw[:]); nval > val {
						u, v, w, val = nu, nv, nw, nval
						eta *= 1.5
						improved = true
						break
					}
				}
				eta *= 0.5
			}
			if !improved {
				break
			}
		}
		if val > best {
			best = val
		}
	}
	return best
}

// S2SpectrumFromSeed replays SampleS2's RNG consumption (scale draw, then the
// 7x7 Gaussian matrix, symmetrised and made traceless) and returns the scale s
// and the eigenvalues of S. g = exp(s S), so ||g||_op = exp(s * max ev).
func S2SpectrumFromSeed(seed uint64) (s float64, ev [7]float64) {
	rng := newRNG(seed ^ r3SeedPsiS2)
	u := rng.Float64()
	s = r3SMin + r3SSpan*u
	var G, S [7][7]float64
	for i := 0; i < 7; i++ {
		for j := 0; j < 7; j++ {
			G[i][j] = rng.NormFloat64()
		}
	}
	tr := 0.0
	for i := 0; i < 7; i++ {
		for j := 0; j < 7; j++ {
			S[i][j] = 0.5 * (G[i][j] + G[j][i])
		}
		tr += S[i][i]
	}
	for i := 0; i < 7; i++ {
		S[i][i] -= tr / 7
	}
	ev, _ = jacobiEigVec7(S)
	return s, ev
}

// GOpCubed is ||g||_op^3 for the seed's S2 deformation g = exp(sS): the bound
// arch seq 57 asked for (comass(g*phi) <= ||g||_op^3, before the Frobenius match).
func GOpCubed(seed uint64) float64 {
	s, ev := S2SpectrumFromSeed(seed)
	hi := math.Inf(-1)
	for _, e := range ev {
		hi = math.Max(hi, e)
	}
	return math.Exp(3 * s * hi)
}

// PostHoc holds the per-seed diagnostics. Zero means "not applicable".
type PostHoc struct {
	Seed         uint64
	Stratum      string
	PsiComass    float64 // K-psi / K-psigram form: S2 on even (definite) seeds, S1-split on odd seeds
	PsiComassChk float64 // same form, independent restart set (convergence check)
	PsiS1Comass  float64 // K-psi-S1 form: S1-definite (even seeds only)
	GOp3         float64 // ||g||_op^3 (even seeds only)
	S2S, S2Dist  float64 // S2 scale and ||psi - phi||/sqrt(42) (even seeds only)
}

// PostHocComass computes the diagnostics for one grid seed. All forms are
// regenerated from the seed; the frozen samplers are called unchanged.
func PostHocComass(seed uint64) PostHoc {
	p := PostHoc{Seed: seed, Stratum: R3Stratum(seed)}
	est := func(f *Form3, tag uint64) float64 {
		return ComassEstimate(f, newRNG(seed^tag), postHocStart, postHocIters)
	}
	if p.Stratum == "definite" {
		d := SampleS2(seed)
		p.PsiComass, p.PsiComassChk = est(d.Form, postHocSeedA), est(d.Form, postHocSeedB)
		p.GOp3, p.S2S, p.S2Dist = GOpCubed(seed), d.S, d.Dist
		if s1, ok := SampleS1(seed, "definite"); ok {
			p.PsiS1Comass = est(s1.Form, postHocSeedA^1)
		}
	} else if s1, ok := SampleS1(seed, "split"); ok {
		p.PsiComass, p.PsiComassChk = est(s1.Form, postHocSeedA), est(s1.Form, postHocSeedB)
	}
	return p
}
